content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-26-group-buy-004

=== 用户原始指令 (query.txt) ===
弄个拼单卡 口味能打勾 那个已拼杯数会变 点一下能跳到点单app 底下写拼单成功

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个拼单卡 口味能打勾 那个已拼杯数会变 点一下能跳到点单app 底下写拼单成功",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "groupBuy": {
      "title": {
        "type": "string",
        "description": "拼单卡标题",
        "sampleValue": "奶茶拼单"
      },
      "joinedCupsText": {
        "type": "string",
        "description": "已拼杯数展示文本，会随拼单进度变化",
        "sampleValue": "已拼 8 杯"
      },
      "joinedCups": {
        "type": "number",
        "description": "已拼杯数数值，用于进度展示",
        "sampleValue": 8
      },
      "targetCups": {
        "type": "number",
        "description": "拼单目标杯数，用于进度总量",
        "sampleValue": 10
      },
      "statusText": {
        "type": "string",
        "description": "拼单当前确认状态",
        "sampleValue": "拼单成功"
      },
      "flavorGroup": {
        "type": "string",
        "description": "口味复选框分组名",
        "sampleValue": "drinkFlavor"
      },
      "flavors": {
        "milkTea": {
          "label": {
            "type": "string",
            "description": "第一项口味名称",
            "sampleValue": "原味"
          },
          "value": {
            "type": "string",
            "description": "第一项口味值",
            "sampleValue": "original"
          },
          "selected": {
            "type": "boolean",
            "description": "第一项口味是否已勾选",
            "sampleValue": true
          }
        },
        "fruitTea": {
          "label": {
            "type": "string",
            "description": "第二项口味名称",
            "sampleValue": "果茶"
          },
          "value": {
            "type": "string",
            "description": "第二项口味值",
            "sampleValue": "fruit"
          },
          "selected": {
            "type": "boolean",
            "description": "第二项口味是否已勾选",
            "sampleValue": false
          }
        },
        "cheese": {
          "label": {
            "type": "string",
            "description": "第三项口味名称",
            "sampleValue": "芝士"
          },
          "value": {
            "type": "string",
            "description": "第三项口味值",
            "sampleValue": "cheese"
          },
          "selected": {
            "type": "boolean",
            "description": "第三项口味是否已勾选",
            "sampleValue": true
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/person_3_fill.svg",
      "description": "三人组实心图标，适合用于拼单、团购、群组成员等多人协作场景的视觉识别。"
    }
  ]
}

